    {
        static $typeMap = [ // abstract type => php type
            'smallint' => 'integer',
            'integer' => 'integer',
            'boolean' => 'boolean',
            'float' => 'double',
        'binary' => 'resource', // THIS WAS MISSING!
        ];
        if (isset($typeMap[$column->type])) {
            if ($column->type === 'integer') {
                return $column->unsigned ? 'string' : 'integer';
            } else {
                return $typeMap[$column->type];
            }
        } else {
            return 'string';
        }
    }
